This Terraform configuration creates an AWS S3 bucket, an SNS topic, and configures the bucket to publish an SNS notification whenever a new object with the `.log` suffix is created in the bucket.

Per your instruction, no IAM or SNS topic policies are included.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = ">= 3.5"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where resources will be created."
  type        = string
  default     = "us-east-1"
}

variable "bucket_name_prefix" {
  description = "Prefix for the S3 bucket name."
  type        = string
  default     = "log-notification-bucket"
}

variable "sns_topic_name" {
  description = "Name of the SNS topic."
  type        = string
  default     = "s3-log-object-created-topic"
}

resource "random_id" "suffix" {
  byte_length = 4
}

resource "aws_s3_bucket" "logs" {
  bucket = "${var.bucket_name_prefix}-${random_id.suffix.hex}"
